+import { createEventCard } from "./event-card.js";
+
+export function buildAgenda(events) {
+  return sortChronologically(events, createEventCard);
+}
+
+// Maps each event (validating it first) and returns the results ordered by
+// startsAt ascending; ties keep input order. The input array is not touched.
+export function sortChronologically(events, build) {
+  return events
+    .map((event) => ({ value: build(event), time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time)
+    .map(({ value }) => value);
+}

